def check_digest_retention(instance: Any, schema: dict, st: store.Store, base_id: str | None, path: str) -> list[str]:
    """For every x-opensip-digest field, require retained preimage as the annotation says."""
    errors = []
    for sch, sid in iter_subschemas(schema, base_id):
        props = sch.get("properties") or {}
        if isinstance(instance, dict):
            for k, v in instance.items():
                psch = props.get(k)
