            item_schema = sch.get("items") or {}
            for i, item in enumerate(instance):
                errors.extend(check_digest_retention(item, item_schema, st, sid, f"{path}[{i}]"))
        for key in ("oneOf", "anyOf"):
            alts = sch.get(key)
            if isinstance(alts, list):
                for alt in alts:
                    try:
