def _bare(digest: str) -> str:
    if ":" in digest:
        return digest.split(":")[-1]
    return digest


def _require_digest(value: str, annot: dict, st: store.Store, path: str) -> str | None:
    rep = annot.get("representation")
    retention = annot.get("retention")
    if retention == "derived":
        return None  # recomputed elsewhere
    bare = _bare(value)
    if rep in ("raw-artifact", "canonical-record", "framed-body-identity"):
        if bare not in st.blobs and value not in st.blobs:
            return f"{path}: {rep} digest {bare} not retained in blobs"
        return None
    if rep == "h-identity":
        # retained as typed id or sha256:hex frame
        domain = annot.get("domain")
        domain_set = annot.get("domainSet")
        candidates = [value]
        if value.startswith("sha256:"):
            candidates.append(value)
        else:
            if len(bare) == 64:
                candidates.append("sha256:" + bare)
                prefix = kit_schemas.PREFIX_TO_IDENTITY_DEF
                # reverse prefix
                for pref, defn in {
                    "snapshot": "snapshot2",
                    "plan": "plan2",
                    "run": "run3",
                    "proof-bundle": "proof3",
                    "semantic-evidence": "evidence3",
                    "evaluation-seal": "seal3",
                    "view": "view2",
                    "fact": "fact2",
                    "coverage": "coverage2",
                    "subject-scope": "scope2",
                    "import": "import2",
                    "closure": "closure2",
                    "execution-plan": "exec-plan2",
                    "finding": "finding3",
                    "evaluation-subject": "subject3",
                    "finding-fingerprint": "finding-key2",
                }.items():
                    if domain == pref:
                        candidates.append(f"{defn}:{bare}")
        found = any(c in st.objects for c in candidates) or bare in st.blobs or value in st.objects
        if not found and retention in (None, "preimage", "preimage-frame"):
            # domainSet members stored under sha256:
            if domain_set and ("sha256:" + bare) in st.objects:
                return None
            if any(ident.endswith(bare) for ident in st.objects):
                return None
            return f"{path}: h-identity {value} preimage not retained (representation={rep} domain={domain} domainSet={domain_set})"
        return None
    if rep == "capability-manifest-id":
        return None
    if rep == "by-domain":
        # look up registry; treat as h-identity or canonical-record per byDomain
        return None
    return None


def admit_instance(instance: Any, schema: dict, st: store.Store | None = None, path: str = "") -> dict:
    stock_validate(instance, schema)
    order_errors = walk_order(instance, schema, schema.get("$id"), path)
    digest_errors = []
    if st is not None:
        digest_errors = check_digest_retention(instance, schema, st, schema.get("$id"), path)
    ok = not order_errors and not digest_errors
    if not ok:
        raise AdmitError(
            "ORDER_OR_DIGEST" if order_errors else "DIGEST_RETENTION",
            "; ".join(order_errors + digest_errors),
            path,
        )
    return {
        "stockPass": True,
        "orderPass": True,
        "digestPass": True,
        "admitted": True,
        "path": path,
    }


def admit_identity_record(obj: Any, def_name: str, st: store.Store, path: str) -> dict:
    schema = kit_schemas.wrap_def("urn:opensip:product-v1:identity:v3", def_name)
